from torch.utils.cpp_extension import load_inline

# Define the optimized CUDA kernel with shared memory tiling
matrix_mult_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_SIZE 32
#define UNROLL 4

__global__ void matrix_mult_kernel(const float* A, const float* B, float* C, int N) {
    // Shared memory tiles with padding to avoid bank conflicts
    __shared__ float As[TILE_SIZE][TILE_SIZE + 1];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE + 1];

    int bx = blockIdx.x, by = blockIdx.y;
    int tx = threadIdx.x, ty = threadIdx.y;

    // Calculate row and column of the output element
    int row = by * TILE_SIZE + ty;
    int col = bx * TILE_SIZE + tx;

    float sum = 0.0f;

    // Loop over tiles
    for (int t = 0; t < N; t += TILE_SIZE) {
        // Load tiles into shared memory with coalesced access
        if (row < N && (t + tx) < N) {
            As[ty][tx] = A[row * N + t + tx];
        } else {
            As[ty][tx] = 0.0f;
        }

        if ((t + ty) < N && col < N) {
            Bs[ty][tx] = B[(t + ty) * N + col];
        } else {
            Bs[ty][tx] = 0.0f;
        }

        __syncthreads();

        // Compute partial result with loop unrolling
        for (int k = 0; k < TILE_SIZE; k += UNROLL) {
            #pragma unroll
            for (int i = 0; i < UNROLL; i++) {
                sum += As[ty][k + i] * Bs[k + i][tx];
            }
        }

        __syncthreads();
    }

    // Write result
    if (row < N && col < N) {
        C[row * N + col] = sum;
    }
}

torch::Tensor matrix_mult_cuda(torch::Tensor A, torch::Tensor B) {
    int N = A.size(0);
    auto C = torch::zeros({N, N}, A.options());

    dim3 block_size(TILE_SIZE, TILE_SIZE);
    dim3 grid_size((N + TILE_SIZE - 1) / TILE_SIZE, (N + TILE_SIZE - 1) / TILE_SIZE);

    matrix_mult_kernel<<<grid_size, block_size>>>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), N);

    return C;
}
"""

